import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Card, Row, Col, Badge, Button } from 'react-bootstrap';
import { getProviderProfile, deleteProviderProfile } from '../../services/providerService';

const ProviderProfileView = () => {
  const navigate = useNavigate();
  const [profile, setProfile] = useState(null);

  useEffect(() => {
    const fetchProfile = async () => {
      const res = await getProviderProfile();
      setProfile(res.data);
    };
    fetchProfile();
  }, []);

  const handleDelete = async () => {
    const confirmDelete = window.confirm("Are you sure you want to delete your profile? This cannot be undone.");
    if (confirmDelete) {
      await deleteProviderProfile();
      navigate('/provider/dashboard');
    }
  };

  if (!profile) return <Container className="py-5">Loading...</Container>;

  const hasProfileData = profile.bio || profile.experience > 0 || profile.hourlyRate > 0 || (profile.serviceAreas && profile.serviceAreas.length > 0) || (profile.specializations && profile.specializations.length > 0);

  return (
    <Container className="py-5">
      <Card className="shadow-sm">
        <Card.Body>
          <div className="d-flex justify-content-between align-items-center mb-4">
            <h2>My Provider Profile</h2>
            <div>
              <Button variant="outline-primary" className="me-2" onClick={() => navigate('/provider/edit-profile')}>
                Edit Profile
              </Button>
              <Button variant="outline-success" onClick={() => navigate('/provider/dashboard')}>
                Back to Dashboard
              </Button>
            </div>
          </div>
          <Row>
            <Col md={8}>
              <p>
                <strong>Bio:</strong> {profile.bio ? profile.bio : <span className="text-muted fst-italic">Not selected</span>}
              </p>
              <p>
                <strong>Experience:</strong> {profile.experience ? `${profile.experience} years` : <span className="text-muted fst-italic">Not selected</span>}
              </p>
              <p>
                <strong>Hourly Rate:</strong> {profile.hourlyRate ? `$${profile.hourlyRate}/hr` : <span className="text-muted fst-italic">Not selected</span>}
              </p>
              <p>
                <strong>Service Areas:</strong> {profile.serviceAreas && profile.serviceAreas.length > 0 ? profile.serviceAreas.join(', ') : <span className="text-muted fst-italic">Not selected</span>}
              </p>
              <div className="mt-3">
                <strong>Specializations: </strong>
                {profile.specializations && profile.specializations.length > 0 ? (
                  profile.specializations.map(spec => (
                    <Badge bg="success" className="me-2" key={spec._id}>{spec.name}</Badge>
                  ))
                ) : (
                  <span className="text-muted fst-italic">Not selected</span>
                )}
              </div>
            </Col>
          </Row>

          {hasProfileData && (
            <div className="mt-5 pt-4 border-top">
              <Button variant="danger" onClick={handleDelete}>
                Delete Profile
              </Button>
            </div>
          )}
        </Card.Body>
      </Card>
    </Container>
  );
};

export default ProviderProfileView;
